def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_coops = sum(1 for h in history if h[1] == 'C')
    opp_coop_rate = opp_coops / n

    if opp_coop_rate < 0.3:
        return 'D'

    ret_count = 0
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'D':
            ret_count += 1

    if ret_count > 0:
        if opp_coop_rate >= 0.5:
            return 'C'
        else:
            return 'D'

    recent = history[-5:]
    recent_opp_def = sum(1 for h in recent if h[1] == 'D')
    if recent_opp_def >= 2:
        return 'D'

    if n < 30:
        return 'C'

    return 'D'
